arguments.command:
cat > /tmp/rosswork/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) echo "x-access-token" ;;
  *assword*) echo "$GITHUB_TOKEN" ;;
  *) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod 700 /tmp/rosswork/askpass.sh
GIT_ASKPASS=/tmp/rosswork/askpass.sh GIT_TERMINAL_PROMPT=0 git -C /tmp/rossconv push origin HEAD:refs/heads/friend/ross 2>&1 | tail -5
